// NOTE: Assertions have been autogenerated by utils/update_cc_test_checks.py UTC_ARGS: --check-globals none --version 6
// REQUIRES: x86-registered-target
// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -emit-llvm %s -o - | FileCheck %s

// A struct output with a register constraint is returned as an integer and
// stored to the destination. The store keeps the destination's volatility, and
// it writes only the destination's bits when the output is tied to a larger
// input, which makes the asm return the input's type.

struct C {
  char a, b;
};

struct S {
  float a, b;
};

// CHECK-LABEL: define dso_local void @test_volatile(
// CHECK-SAME: ptr noundef [[P:%.*]]) #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[P_ADDR:%.*]] = alloca ptr, align 8
// CHECK-NEXT:    store ptr [[P]], ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[TMP0:%.*]] = load ptr, ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[TMP1:%.*]] = call i64 asm "", "=r,~{dirflag},~{fpsr},~{flags}"() #[[ATTR1:[0-9]+]], !srcloc [[META1:![0-9]+]]
// CHECK-NEXT:    store volatile i64 [[TMP1]], ptr [[TMP0]], align 4
// CHECK-NEXT:    ret void
//
void test_volatile(volatile struct S *p) {
  asm("" : "=r"(*p));
}

// CHECK-LABEL: define dso_local void @test_tied_int(
// CHECK-SAME: ptr noundef [[P:%.*]], i32 noundef [[X:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[P_ADDR:%.*]] = alloca ptr, align 8
// CHECK-NEXT:    [[X_ADDR:%.*]] = alloca i32, align 4
// CHECK-NEXT:    store ptr [[P]], ptr [[P_ADDR]], align 8
// CHECK-NEXT:    store i32 [[X]], ptr [[X_ADDR]], align 4
// CHECK-NEXT:    [[TMP0:%.*]] = load ptr, ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[TMP1:%.*]] = load i32, ptr [[X_ADDR]], align 4
// CHECK-NEXT:    [[TMP2:%.*]] = call i32 asm "", "=r,0,~{dirflag},~{fpsr},~{flags}"(i32 [[TMP1]]) #[[ATTR1]], !srcloc [[META2:![0-9]+]]
// CHECK-NEXT:    [[TMP3:%.*]] = trunc i32 [[TMP2]] to i16
// CHECK-NEXT:    store i16 [[TMP3]], ptr [[TMP0]], align 1
// CHECK-NEXT:    ret void
//
void test_tied_int(struct C *p, int x) {
  asm("" : "=r"(*p) : "0"(x));
}

// CHECK-LABEL: define dso_local void @test_tied_pointer(
// CHECK-SAME: ptr noundef [[P:%.*]], ptr noundef [[X:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[P_ADDR:%.*]] = alloca ptr, align 8
// CHECK-NEXT:    [[X_ADDR:%.*]] = alloca ptr, align 8
// CHECK-NEXT:    store ptr [[P]], ptr [[P_ADDR]], align 8
// CHECK-NEXT:    store ptr [[X]], ptr [[X_ADDR]], align 8
// CHECK-NEXT:    [[TMP0:%.*]] = load ptr, ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[TMP1:%.*]] = load ptr, ptr [[X_ADDR]], align 8
// CHECK-NEXT:    [[TMP2:%.*]] = call ptr asm "", "=r,0,~{dirflag},~{fpsr},~{flags}"(ptr [[TMP1]]) #[[ATTR1]], !srcloc [[META3:![0-9]+]]
// CHECK-NEXT:    [[TMP3:%.*]] = ptrtoint ptr [[TMP2]] to i16
// CHECK-NEXT:    store i16 [[TMP3]], ptr [[TMP0]], align 1
// CHECK-NEXT:    ret void
//
void test_tied_pointer(struct C *p, void *x) {
  asm("" : "=r"(*p) : "0"(x));
}

